PREFIX gleif-L1: <https://www.gleif.org/ontology/L1/>
PREFIX gleif-base: <https://www.gleif.org/ontology/Base/>
PREFIX kgx: <https://example.org/gleif-kg/ontology/>

SELECT ?branchLegalName WHERE {
  # Find the entity with legal name "Caldic B.V."
  ?headOffice a gleif-L1:RegisteredEntity ;
              gleif-L1:hasLegalName "Caldic B.V." .

  # Find branches whose parent is this head office
  ?branch kgx:hasBranchParent ?headOffice ;
          gleif-L1:hasLegalName ?branchLegalName .
}

