PREFIX gleif-base: <https://www.gleif.org/ontology/Base/>
PREFIX gleif-L1: <https://www.gleif.org/ontology/L1/>
PREFIX jur: <https://www.gleif.org/data/jurisdiction/>

SELECT (COUNT(?e) AS ?count)
WHERE {
  ?e gleif-base:hasRegistrationStatus gleif-L1:ISSUED ;
     gleif-base:hasLegalJurisdiction jur:DE .
}

PREFIX gleif-base: <https://www.gleif.org/ontology/Base/>
PREFIX gleif-L1: <https://www.gleif.org/ontology/L1/>

SELECT (COUNT(DISTINCT ?e) AS ?count)
WHERE {
  ?e gleif-base:hasRegistrationStatus gleif-L1:LAPSED .
}

PREFIX gleif-L1: <https://www.gleif.org/ontology/L1/>
SELECT (COUNT(?e) AS ?fundCount)
WHERE {
  ?e a gleif-L1:Fund .
}

PREFIX gleif-base: <https://www.gleif.org/ontology/Base/>
PREFIX gleif-L1: <https://www.gleif.org/ontology/L1/>
PREFIX lei: <https://www.gleif.org/data/lei/>
PREFIX jur: <https://www.gleif.org/data/jurisdiction/>

SELECT (COUNT(?e) AS ?count)
WHERE {
  ?e a gleif-base:Entity ;
     gleif-base:hasLegalJurisdiction jur:IT ;
     gleif-base:hasRegistrationStatus gleif-L1:ISSUED .
}

PREFIX gleif-L1: <https://www.gleif.org/ontology/L1/>
SELECT (COUNT(?e) AS ?count)
WHERE {
  ?e a gleif-L1:SoleProprietor .
}

PREFIX gleif-base: <https://www.gleif.org/ontology/Base/>

SELECT (COUNT(?e) AS ?count)
WHERE {
  ?e a gleif-base:Entity ;
     gleif-base:hasEntityStatus gleif-base:INACTIVE .
}

PREFIX gleif-base: <https://www.gleif.org/ontology/Base/>
PREFIX gleif-L1: <https://www.gleif.org/ontology/L1/>

SELECT ?jur (COUNT(?e) AS ?cnt)
WHERE {
  ?e a gleif-base:Entity ;
     gleif-base:hasLegalJurisdiction ?jur ;
     gleif-base:hasRegistrationStatus gleif-L1:ISSUED .
}
GROUP BY ?jur
ORDER BY DESC(?cnt)
LIMIT 5

PREFIX gleif-re: <https://www.gleif.org/ontology/ReportingException/>
SELECT ?reason (COUNT(?exception) AS ?count)
WHERE {
  ?exception a gleif-re:ReportingException ;
             gleif-re:hasExceptionReason ?reason .
}
GROUP BY ?reason
ORDER BY DESC(?count)
LIMIT 5

PREFIX gleif-L1: <https://www.gleif.org/ontology/L1/>
PREFIX gleif-base: <https://www.gleif.org/ontology/Base/>
PREFIX gleif-re: <https://www.gleif.org/ontology/ReportingException/>
PREFIX kgx: <https://example.org/gleif-kg/ontology/>

SELECT ?reason WHERE {
  ?e a gleif-L1:RegisteredEntity ;
     gleif-L1:hasLegalName "M-M FRANCE" .
  OPTIONAL { ?e kgx:hasDirectConsolidationParent ?parent . }
  FILTER (!bound(?parent))
  ?ex gleif-re:hasReportingEntity ?e ;
      gleif-re:hasExceptionReason ?reason .
}

